INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_aj-7-present-perfect_0','Jak tvoříme present perfect?',ARRAY['did + infinitiv','will + infinitiv','was/were + sloveso -ing','have/has + 3. tvar slovesa']::TEXT[],3,'She has played.',1,ARRAY[]::TEXT[],NULL,0,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_1','Doplň: I … seen that film.',ARRAY['am','have','had','has']::TEXT[],1,'S I se používá have.',1,ARRAY[]::TEXT[],NULL,1,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_2','Doplň: She … finished her homework.',ARRAY['have','has','is','had']::TEXT[],1,'S she se používá has.',1,ARRAY[]::TEXT[],NULL,2,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_3','Jaký je 3. tvar slovesa go?',ARRAY['goed','went','gone','going']::TEXT[],2,'go – went – gone.',2,ARRAY[]::TEXT[],NULL,3,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_4','Jaký je 3. tvar slovesa eat?',ARRAY['ate','eated','eaten','eating']::TEXT[],2,'eat – ate – eaten.',2,ARRAY[]::TEXT[],NULL,4,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_5','Doplň: We … never been to London.',ARRAY['did','has','have','are']::TEXT[],2,'We have never been.',2,ARRAY[]::TEXT[],NULL,5,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_6','Doplň: I have lived here … 2020.',ARRAY['from','during','since','for']::TEXT[],2,'Since se používá s časovým bodem.',3,ARRAY[]::TEXT[],NULL,6,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_7','Doplň: I have lived here … five years.',ARRAY['ago','from','since','for']::TEXT[],3,'For se používá s délkou trvání.',3,ARRAY[]::TEXT[],NULL,7,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_8','Jak se zeptáme: Byl jsi někdy v Paříži?',ARRAY['Have you ever went to Paris?','Have you ever been to Paris?','Are you ever been to Paris?','Did you ever be to Paris?']::TEXT[],1,'Have you ever + 3. tvar.',3,ARRAY[]::TEXT[],NULL,8,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_9','Doplň: He hasn''t called me ….',ARRAY['ever','yet','since','already']::TEXT[],1,'Yet se používá v záporu a otázce.',4,ARRAY[]::TEXT[],NULL,9,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_10','Doplň: I have … eaten lunch. (už)',ARRAY['already','yet','never','ever']::TEXT[],0,'Already = už.',4,ARRAY[]::TEXT[],NULL,10,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_11','Která věta je správně?',ARRAY['She has lost her keys.','She has lose her keys.','She has losted her keys.','She have lost her keys.']::TEXT[],0,'Lose – lost – lost.',4,ARRAY[]::TEXT[],NULL,11,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_12','Která z vět je správná?',ARRAY['I saw him yesterday.','I did saw him yesterday.','I have saw him yesterday.','I have seen him yesterday.']::TEXT[],0,'S yesterday používáme past simple.',5,ARRAY[]::TEXT[],NULL,12,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_13','Co znamená věta: I have lost my phone.',ARRAY['Ztratil jsem telefon (a stále ho nemám).','Ztrácel jsem telefon.','Budu ztrácet telefon.','Ztratil jsem telefon minulý týden.']::TEXT[],0,'Present perfect spojuje minulost s přítomností.',5,ARRAY[]::TEXT[],NULL,13,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_14','Vyber správnou větu.',ARRAY['How long do you know her?','How long have you known her?','How long are you knowing her?','How long did you have known her?']::TEXT[],1,'How long + present perfect pro trvající stav.',5,ARRAY[]::TEXT[],NULL,14,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_15','Doplň: They … lived in Brno for ten years. (have)',ARRAY['has','are','have','had']::TEXT[],2,'They → have.',1,ARRAY[]::TEXT[],NULL,15,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_16','Doplň: He … visited London. (has)',ARRAY['had','is','has','have']::TEXT[],2,'He/she/it → has.',1,ARRAY[]::TEXT[],NULL,16,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_17','Doplň: We … already finished our lunch. (have)',ARRAY['had','has','are','have']::TEXT[],3,'We → have.',1,ARRAY[]::TEXT[],NULL,17,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_18','Doplň: She … worked here since May. (has)',ARRAY['had','has','have','is']::TEXT[],1,'She → has.',1,ARRAY[]::TEXT[],NULL,18,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_19','Doplň: You … been to the zoo. (have)',ARRAY['are','have','has','had']::TEXT[],1,'You → have.',1,ARRAY[]::TEXT[],NULL,19,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_20','3. tvar slovesa "play" je…',ARRAY['played''s','played (ne)','plaid','played']::TEXT[],3,'Play → played (pravidelné).',2,ARRAY[]::TEXT[],NULL,20,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_21','3. tvar slovesa "write" je…',ARRAY['writed','wrote','written','writen']::TEXT[],2,'Write → written.',2,ARRAY[]::TEXT[],NULL,21,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_22','3. tvar slovesa "take" je…',ARRAY['taken','took','taking','taked']::TEXT[],0,'Take → taken.',2,ARRAY[]::TEXT[],NULL,22,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_23','3. tvar slovesa "drive" je…',ARRAY['drove','driving','drived','driven']::TEXT[],3,'Drive → driven.',2,ARRAY[]::TEXT[],NULL,23,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_24','3. tvar slovesa "buy" je…',ARRAY['buyed','bought','buying','buy']::TEXT[],1,'Buy → bought.',2,ARRAY[]::TEXT[],NULL,24,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_25','Doplň: I … just … the email. (have sent)',ARRAY['have / send','has / send','had / sent','have / sent']::TEXT[],3,'Have sent = právě jsem poslal.',3,ARRAY[]::TEXT[],NULL,25,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_26','Doplň: She … never … to Italy. (has been)',ARRAY['has / gone','has / been','was / been','have / been']::TEXT[],1,'Has been = nikdy nebyla.',3,ARRAY[]::TEXT[],NULL,26,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_27','Doplň: They … lost their keys. (have)',ARRAY['are','have','has','had']::TEXT[],1,'They → have.',3,ARRAY[]::TEXT[],NULL,27,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_28','Doplň: We have known each other … 2015. (since)',ARRAY['for','since','from','during']::TEXT[],1,'Since + rok = od roku.',3,ARRAY[]::TEXT[],NULL,28,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_29','Doplň: We have known each other … three years. (for)',ARRAY['during','for','since','from']::TEXT[],1,'For + doba = po dobu.',3,ARRAY[]::TEXT[],NULL,29,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_30','Zápor: "He has finished the project."',ARRAY['He hasn''t finished the project.','He doesn''t finished the project.','He not has finished the project.','He hasn''t finish the project.']::TEXT[],0,'Zápor: hasn''t + 3. tvar.',4,ARRAY[]::TEXT[],NULL,30,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_31','Doplň: Have you … seen this film? (ever, někdy)',ARRAY['never','already','ever','yet']::TEXT[],2,'Ever = někdy (v otázkách).',4,ARRAY[]::TEXT[],NULL,31,'c_aj-7-present-perfect',NULL,NOW()),
('q_aj-7-present-perfect_32','Doplň: I have … seen that film. (never)',ARRAY['never','yet','ever','already']::TEXT[],0,'Never = nikdy (v kladné větě).',4,ARRAY[]::TEXT[],NULL,32,'c_aj-7-present-perfect',NULL,NOW()),
