('q_aj-8-reported-speech_30','Přeměň: ''Don''t run in the hall!'' he said.',ARRAY['He said us not to run in the hall.','He told us not to run in the hall.','He told us don''t run in the hall.','He said not run in the hall.']::TEXT[],1,'Zákaz → told + not to + inf.',3,ARRAY[]::TEXT[],NULL,30,'c_aj-8-reported-speech',NULL,NOW()),
('q_aj-8-reported-speech_31','Která věta z nepřímé řeči je správně?',ARRAY['She said she was tired.','She said she tired.','She said she was tire.','She said she is tired.']::TEXT[],0,'Posun času: is → was.',4,ARRAY[]::TEXT[],NULL,31,'c_aj-8-reported-speech',NULL,NOW()),
('q_aj-8-reported-speech_32','Přeměň: ''I bought a car yesterday,'' he said.',ARRAY['He said he bought a car the day before.','He said he bought a car yesterday.','He said he had bought a car the day before.','He said he had buy a car the day before.']::TEXT[],2,'Past simple → past perfect; yesterday → the day before.',4,ARRAY[]::TEXT[],NULL,32,'c_aj-8-reported-speech',NULL,NOW()),
('q_aj-8-reported-speech_33','Přeměň: ''We are leaving tomorrow,'' they said.',ARRAY['They said they were leaving the next day.','They said they leaving the next day.','They said they would leave tomorrow.','They said they are leaving the next day.']::TEXT[],0,'Present continuous → past continuous; tomorrow → the next day.',4,ARRAY[]::TEXT[],NULL,33,'c_aj-8-reported-speech',NULL,NOW()),
('q_aj-8-reported-speech_34','Přeměň: ''I''m going to visit my aunt,'' she said.',ARRAY['She said she was going to visit her aunt.','She said she is going to visit her aunt.','She said she would visit her aunt.','She said she going to visit her aunt.']::TEXT[],0,'Be going to → was going to.',4,ARRAY[]::TEXT[],NULL,34,'c_aj-8-reported-speech',NULL,NOW()),
('q_aj-8-reported-speech_35','Přeměň: ''Please help me,'' he said to her.',ARRAY['He asked her to help him.','He told her help me.','He asked her help him.','He said her to help him.']::TEXT[],0,'Prosba → asked + to + inf.',4,ARRAY[]::TEXT[],NULL,35,'c_aj-8-reported-speech',NULL,NOW()),
('q_aj-8-reported-speech_36','Přeměň: ''I have never been to Spain,'' she said.',ARRAY['She said she never been to Spain.','She said she has never been to Spain.','She said she had never been to Spain.','She said she had never be to Spain.']::TEXT[],2,'Present perfect → past perfect; never zůstává.',5,ARRAY[]::TEXT[],NULL,36,'c_aj-8-reported-speech',NULL,NOW()),
('q_aj-8-reported-speech_37','Přeměň: ''You must finish this today,'' he said.',ARRAY['He said I must finish this today.','He said I had to finish that today.','He said I had finish that today.','He said I have to finish that today.']::TEXT[],1,'Must → had to; this → that.',5,ARRAY[]::TEXT[],NULL,37,'c_aj-8-reported-speech',NULL,NOW()),
('q_aj-8-reported-speech_38','Přeměň: ''Can you come to the party?'' she asked me.',ARRAY['She asked me could I come to the party.','She asked me if I could come to the party.','She asked me can I come to the party.','She asked me if I can come to the party.']::TEXT[],1,'Can → could; otázka → if.',5,ARRAY[]::TEXT[],NULL,38,'c_aj-8-reported-speech',NULL,NOW()),
('q_aj-8-reported-speech_39','Přeměň: ''We will meet here next week,'' they said.',ARRAY['They said they will meet here the next week.','They said they meet there the following week.','They said they would meet here next week.','They said they would meet there the following week.']::TEXT[],3,'Will → would; here → there; next week → the following week.',5,ARRAY[]::TEXT[],NULL,39,'c_aj-8-reported-speech',NULL,NOW()),
('q_aj-8-reported-speech_40','Co znamená "He told me that he had moved to London"?',ARRAY['Řekl mi, že se nepřestěhoval do Londýna','Řekl mi, že se přestěhoval do Londýna','Řekl mi, že se přestěhuje do Londýna','Řekl mi, že se do Londýna přestěhuje zítra']::TEXT[],1,'Had moved = předminulý čas (dříve než sdělení).',5,ARRAY[]::TEXT[],NULL,40,'c_aj-8-reported-speech',NULL,NOW()),
